<script setup>
import { computed, onMounted, ref, toRaw } from 'vue'
import UniversalAdminForm from '../components/admin/UniversalAdminForm.vue'
import BackupRestorePanel from '../components/admin/BackupRestorePanel.vue'
import SyntheticDataPanel from '../components/admin/SyntheticDataPanel.vue'
import { ADMIN_FORM_DEFINITIONS } from '../application/admin/adminFormDefinitions.js'
import { AdminService } from '../application/admin/adminService.js'
import { BackupService } from '../application/backup/backupService.js'
import { PerformanceService } from '../application/performance/performanceService.js'
import { getKfeReferenceNow, istDateKey } from '../domain/time/ist.js'
import { deriveLoanPosition, calculatePrepaymentEstimate, paymentAllocationPreview } from '../domain/finance/loanEngine.js'
import { getKfeThemeSettings, setKfeThemeMode } from '../presentation/theme/kfeThemeController.js'

const items=[
 {key:'vehicle',category:'BUSINESS SETUP',title:'Vehicle',icon:'🚗'},
 {key:'driver',category:'BUSINESS SETUP',title:'Driver',icon:'👤'},
 {key:'compliance',category:'VEHICLE RECORDS',title:'Compliance',icon:'✓'},
 {key:'maintenance',category:'VEHICLE RECORDS',title:'Maintenance',icon:'🔧'},
 {key:'loan',category:'FINANCE',title:'Loan',icon:'₹'},
 {key:'prepayment',category:'FINANCE',title:'Prepayments',icon:'↘'},
 {key:'driverTarget',category:'TARGET',title:'Driver Monthly Target',icon:'🎯'},
 {key:'maintenanceRate',category:'TARGET',title:'Maintenance per KM',icon:'KM'}
]
const categories=[...new Set(items.map(x=>x.category))]
const settingsMenu=[{key:'backup',title:'Backup & Restore',icon:'↥'},{key:'application',title:'Application Settings',icon:'⚙'},{key:'reset',title:'Data Reset',icon:'⚠'},{key:'synthetic',title:'Synthetic Data',icon:'🧪'}]
const selected=ref(null),settingsOpen=ref(false),settingsSelected=ref('backup'),masterSelected=ref(null)
const records=ref([]),all=ref({vehicle:[],driver:[],loan:[],compliance:[],maintenance:[],driverTarget:[],breakEvenInputs:[],loanPayment:[],prepayment:[],settlement:[]})
const performanceSnapshot=ref(null),loading=ref(false),error=ref(''),notice=ref('')
const formOpen=ref(false),editing=ref(null),draft=ref({})
const actionKey=ref(null),actionRecord=ref(null),actionDraft=ref({}),paymentCalculated=ref(false),paymentConfirmed=ref(false)
const prepaymentDraft=ref({loanId:'',paidOn:istDateKey(getKfeReferenceNow()),amount:0,reason:'',notes:''}),prepaymentCalculated=ref(false),prepaymentConfirmed=ref(false)
const targetDraft=ref({driverId:'',month:istDateKey(getKfeReferenceNow()).slice(0,7),desiredDriverProfit:0,targetHours:'',targetKm:''})
const maintenanceRateDraft=ref({rate:'',changeDate:istDateKey(getKfeReferenceNow())})
const themeSettings=ref(getKfeThemeSettings())
const money=v=>Number.isFinite(Number(v))?'₹'+Number(v).toLocaleString('en-IN',{maximumFractionDigits:2}):'—'
const clone=v=>structuredClone(toRaw(v))
const live=xs=>(xs||[]).filter(x=>!x?.deletedAt&&!x?.deleted)
function label(key,record){const v=record?.values||record||{};if(key==='vehicle')return [v.registrationNumber,v.make,v.model].filter(Boolean).join(' · ')||record?.id;if(key==='driver')return v.name||record?.id;if(key==='loan')return [v.lender,v.accountReference].filter(Boolean).join(' · ')||record?.id;if(key==='compliance')return v.complianceType||record?.id;if(key==='maintenance')return v.maintenanceType||record?.id;return record?.id||'—'}
const currentItem=computed(()=>items.find(x=>x.key===selected.value)||null)
const masterMode=computed(()=>['vehicle','driver','compliance'].includes(selected.value))
const masterRecord=computed(()=>masterSelected.value?records.value.find(x=>x.id===masterSelected.value)||null:null)
const provisionRange=computed(()=>{
  const now=getKfeReferenceNow()
  const dates=[
    ...live(performanceSnapshot.value?.shifts).map(x=>x.shiftStartAt||x.shiftEndAt),
    ...live(performanceSnapshot.value?.compliance).map(x=>x.validFrom),
    ...live(performanceSnapshot.value?.maintenance).map(x=>x.performedOn)
  ].map(x=>new Date(x)).filter(x=>!Number.isNaN(x.getTime()))
  const from=dates.sort((a,b)=>a-b)[0]||now
  return {from,to:now}
})
const performanceProvisionMetrics=computed(()=>{
  if(!performanceSnapshot.value)return null
  return PerformanceService.getMetrics(performanceSnapshot.value,provisionRange.value)
})
const complianceProvisionFor=computed(()=>record=>{
  if(!record||!performanceSnapshot.value)return 0
  const v=record.values||record
  const from=new Date(v.validFrom), now=getKfeReferenceNow()
  if(Number.isNaN(from.getTime())||from>now)return 0
  const until=new Date(v.validUntil)
  const to=Number.isNaN(until.getTime())?now:new Date(Math.min(until.getTime(),now.getTime()))
  if(to<from)return 0
  const metrics=PerformanceService.getMetrics(performanceSnapshot.value,{from,to})
  return Number.isFinite(Number(metrics?.renewalProvision))?Number(metrics.renewalProvision):0
})
const complianceProvisionTotal=computed(()=>live(records.value).reduce((sum,r)=>sum+complianceProvisionFor.value(r),0))
const maintenanceProvisionTotal=computed(()=>performanceProvisionMetrics.value?Number(performanceProvisionMetrics.value.maintenanceProvision)||0:0)
const provisionPct=(provision,cost)=>cost>0?Math.min(100,Math.max(0,(provision/cost)*100)):0
const currentDefinition=computed(()=>currentItem.value?ADMIN_FORM_DEFINITIONS[currentItem.value.key]:null)
const activeDefinition=computed(()=>{if(!currentDefinition.value)return null;const d=clone(currentDefinition.value);for(const f of d.fields||[]){if(f.key==='vehicleId')f.options=all.value.vehicle.map(x=>({value:x.id,label:label('vehicle',x)}));if(f.key==='driverId')f.options=all.value.driver.map(x=>({value:x.id,label:label('driver',x)}));if(f.key==='loanId')f.options=all.value.loan.map(x=>({value:x.id,label:label('loan',x)}))}return d})
const sourcePayments=id=>live(performanceSnapshot.value?.settlements).filter(x=>x.sourceId===id&&String(x.direction||(x.settlementType==='Receipt'?'IN':'OUT')).toUpperCase()==='OUT')
const sumPayments=id=>sourcePayments(id).reduce((s,x)=>s+(Number(x.amount)||0),0)
const entityFinancial=record=>{if(!record)return null;if(selected.value==='loan'){const loan=live(performanceSnapshot.value?.loans).find(x=>x.id===record.id)||record;const p=deriveLoanPosition({loan,payments:live(performanceSnapshot.value?.loanPayments),prepayments:live(performanceSnapshot.value?.prepayments),asOf:getKfeReferenceNow()});return {principal:Number(loan.principal)||0,paid:p.actualPaid||0,prepaid:p.actualPrepayment||0,remaining:p.outstandingPrincipal||0,emi:p.emi||0,pending:Math.max(0,(p.scheduledDue||0)-(p.actualPaid||0)),overdue:p.totalOverdue||0}}if(selected.value==='maintenance'||selected.value==='compliance'){const v=record.values||record,paid=sumPayments(record.id);return {cost:Number(v.cost)||0,paid,remaining:Math.max(0,(Number(v.cost)||0)-paid)}}return null}
const loanHistory=record=>{const s=performanceSnapshot.value||{};return [...live(s.loanPayments).filter(x=>x.loanId===record.id).map(x=>({kind:'EMI payment',date:x.paidOn,amount:Number(x.amount)||0})),...live(s.prepayments).filter(x=>x.loanId===record.id).map(x=>({kind:'Prepayment',date:x.paidOn,amount:Number(x.amount)||0}))].sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
const sourceHistory=record=>sourcePayments(record.id).sort((a,b)=>String(b.settledOn||'').localeCompare(String(a.settledOn||'')))
const loanSchedule=record=>{const loan=live(performanceSnapshot.value?.loans).find(x=>x.id===record.id)||record;const p=deriveLoanPosition({loan,payments:live(performanceSnapshot.value?.loanPayments),prepayments:live(performanceSnapshot.value?.prepayments),asOf:getKfeReferenceNow()});return p.overdue||[]}
const currentMonth=computed(()=>istDateKey(getKfeReferenceNow()).slice(0,7))
const currentMaintenanceRate=computed(()=>{const now=istDateKey(getKfeReferenceNow());return live(all.value.breakEvenInputs).filter(x=>String(x.values?.effectiveFrom||'')<=now).sort((a,b)=>String(b.values?.effectiveFrom||'').localeCompare(String(a.values?.effectiveFrom||'')))[0]||null})
const targetHistory=computed(()=>live(all.value.driverTarget).sort((a,b)=>String(b.values?.effectiveFrom||'').localeCompare(String(a.values?.effectiveFrom||''))))
const maintenanceHistory=computed(()=>live(all.value.breakEvenInputs).filter(x=>x.values?.maintenanceProvisionPerKm!=null).sort((a,b)=>String(b.values?.effectiveFrom||'').localeCompare(String(a.values?.effectiveFrom||''))))
const driverNames=computed(()=>Object.fromEntries(all.value.driver.map(x=>[x.id,label('driver',x)])))
const groupedItems=computed(()=>categories.map(category=>({category,items:items.filter(x=>x.category===category)})))
function clearMessages(){error.value='';notice.value=''}
function closeAction(){actionKey.value=null;actionRecord.value=null;actionDraft.value={};paymentCalculated.value=false;paymentConfirmed.value=false}
function openItem(key){clearMessages();settingsOpen.value=false;selected.value=key;masterSelected.value=null;formOpen.value=false;editing.value=null;draft.value={};closeAction();if(key==='prepayment')resetPrepayment();if(key==='driverTarget')resetTarget();if(key==='maintenanceRate')resetMaintenanceRate();load()}
function openMasterRecord(record){clearMessages();masterSelected.value=record.id;formOpen.value=false;editing.value=null;draft.value={}}
function backMasterList(){clearMessages();masterSelected.value=null;formOpen.value=false;editing.value=null;draft.value={}}
function masterFieldValue(field,record){const v=record?.values?.[field.key];if(v===undefined||v===null||v==='')return '—';if(field.type==='checkbox')return v?'Yes':'No';if(field.type==='select'){if(field.key==='vehicleId')return label('vehicle',all.value.vehicle.find(x=>x.id===v));if(field.key==='driverId')return label('driver',all.value.driver.find(x=>x.id===v));const opts=field.options||[];const found=opts.find(x=>x?.value===v);return found?.label||v}return String(v)}
function back(){selected.value=null;settingsOpen.value=false;formOpen.value=false;editing.value=null;draft.value={};closeAction();clearMessages()}
function openSettings(){clearMessages();selected.value=null;settingsOpen.value=true}
function chooseSetting(key){settingsSelected.value=key;clearMessages()}
function chooseTheme(mode){themeSettings.value={...themeSettings.value,mode};setKfeThemeMode(mode);notice.value='Theme set to '+(mode==='light'?'Light':mode==='dark'?'Dark':'Auto')+'.'}
function add(){editing.value=null;draft.value={};formOpen.value=true}
function edit(record){editing.value=record.id;draft.value=clone(record.values||{});formOpen.value=true}
function updateDraft(v){draft.value={...v}}
function openAction(kind,record){actionKey.value=kind;actionRecord.value=record;paymentCalculated.value=false;paymentConfirmed.value=false;const f=entityFinancial(record);actionDraft.value=kind==='loanPayment'?{loanId:record.id,paidOn:istDateKey(getKfeReferenceNow()),amount:Math.max(0,Number(f?.overdue||f?.emi||0))}:{settledOn:istDateKey(getKfeReferenceNow()),amount:Math.max(0,Number(f?.remaining||0))}}
const loanPaymentPreview=computed(()=>{if(actionKey.value!=='loanPayment'||!actionRecord.value||!paymentCalculated.value)return null;const loan=live(performanceSnapshot.value?.loans).find(x=>x.id===actionRecord.value.id)||actionRecord.value;return paymentAllocationPreview({loan,payments:live(performanceSnapshot.value?.loanPayments),prepayments:live(performanceSnapshot.value?.prepayments),amount:Number(actionDraft.value.amount)||0,paidOn:actionDraft.value.paidOn})})
function resetPrepayment(){prepaymentDraft.value={loanId:'',paidOn:istDateKey(getKfeReferenceNow()),amount:0,reason:'',notes:''};prepaymentCalculated.value=false;prepaymentConfirmed.value=false}
function selectPrepaymentLoan(id){const loan=all.value.loan.find(x=>x.id===id);const p=loan?deriveLoanPosition({loan,payments:live(performanceSnapshot.value?.loanPayments),prepayments:live(performanceSnapshot.value?.prepayments),asOf:getKfeReferenceNow()}):null;prepaymentDraft.value={...prepaymentDraft.value,loanId:id,amount:Math.max(0,Number(p?.outstandingPrincipal||0))};prepaymentCalculated.value=false;prepaymentConfirmed.value=false}
const selectedPrepaymentLoan=computed(()=>all.value.loan.find(x=>x.id===prepaymentDraft.value.loanId)||null)
const selectedPrepaymentPosition=computed(()=>selectedPrepaymentLoan.value?deriveLoanPosition({loan:selectedPrepaymentLoan.value,payments:live(performanceSnapshot.value?.loanPayments),prepayments:live(performanceSnapshot.value?.prepayments),asOf:getKfeReferenceNow()}):null)
const prepaymentEstimate=computed(()=>{const loan=selectedPrepaymentLoan.value;if(!loan||!prepaymentCalculated.value)return null;const estimate=calculatePrepaymentEstimate({loan,payments:live(performanceSnapshot.value?.loanPayments),prepayments:live(performanceSnapshot.value?.prepayments),amount:Number(prepaymentDraft.value.amount)||0,paidOn:prepaymentDraft.value.paidOn});if(!estimate.available)return estimate;const h={id:'preview',loanId:loan.id,paidOn:prepaymentDraft.value.paidOn,amount:estimate.appliedAmount,status:'Applied'};const before=deriveLoanPosition({loan,payments:live(performanceSnapshot.value?.loanPayments),prepayments:live(performanceSnapshot.value?.prepayments),asOf:prepaymentDraft.value.paidOn});const after=deriveLoanPosition({loan,payments:live(performanceSnapshot.value?.loanPayments),prepayments:[...live(performanceSnapshot.value?.prepayments),h],asOf:prepaymentDraft.value.paidOn});const bd=before.scheduledFinalDate?new Date(before.scheduledFinalDate):null,ad=after.scheduledFinalDate?new Date(after.scheduledFinalDate):null;return {...estimate,reducedMonths:bd&&ad?Math.max(0,Math.round((bd.getFullYear()-ad.getFullYear())*12+(bd.getMonth()-ad.getMonth()))):0,remainingAfter:after.outstandingPrincipal,interestRemainingAfter:after.remainingInterest}})
function resetTarget(){targetDraft.value={driverId:'',month:currentMonth.value,desiredDriverProfit:0}}
function resetMaintenanceRate(){maintenanceRateDraft.value={rate:currentMaintenanceRate.value?.values?.maintenanceProvisionPerKm??'',changeDate:istDateKey(getKfeReferenceNow())}}
function monthStart(m){return (m||currentMonth.value)+'-01'}
async function saveTarget(){clearMessages();loading.value=true;try{if(!targetDraft.value.driverId||Number(targetDraft.value.desiredDriverProfit)<0)throw new Error('Driver and monthly target are required.');await AdminService.save('driverTarget',{driverId:targetDraft.value.driverId,effectiveFrom:monthStart(targetDraft.value.month),desiredDriverProfit:Number(targetDraft.value.desiredDriverProfit),active:true});notice.value='Monthly driver target saved.';await load()}catch(e){error.value=e.validation?Object.values(e.validation).join(' '):e.message||'Unable to save target.'}finally{loading.value=false}}
async function saveMaintenanceRate(){clearMessages();loading.value=true;try{const rate=Number(maintenanceRateDraft.value.rate);if(!Number.isFinite(rate)||rate<0)throw new Error('Maintenance per KM must be zero or greater.');await AdminService.save('breakEvenInputs',{effectiveFrom:maintenanceRateDraft.value.changeDate,maintenanceProvisionPerKm:rate});notice.value='Maintenance per KM rate saved.';await load()}catch(e){error.value=e.validation?Object.values(e.validation).join(' '):e.message||'Unable to save rate.'}finally{loading.value=false}}
async function save(values){clearMessages();loading.value=true;try{const id=editing.value,payload=(selected.value==='compliance'||selected.value==='maintenance')?{...values,cost:Number(values.cost)||0}:values;const saved=await AdminService.save(selected.value,payload,id);if(id===null&&(selected.value==='compliance'||selected.value==='maintenance')&&Number(payload.cost)>0)await AdminService.save('settlement',{settlementType:'Payment',sourceType:selected.value==='maintenance'?'Maintenance':'Compliance',sourceId:saved.id,settledOn:selected.value==='maintenance'?payload.performedOn:payload.validFrom,amount:Number(payload.cost)});notice.value=(id!==null?'Record updated.':'Record created.');formOpen.value=false;editing.value=null;await load()}catch(e){error.value=e.validation?Object.values(e.validation).join(' '):e.message||'Save failed.'}finally{loading.value=false}}
async function saveLoanPayment(){clearMessages();loading.value=true;try{await AdminService.save('loanPayment',actionDraft.value);notice.value='Loan payment recorded.';closeAction();await load()}catch(e){error.value=e.validation?Object.values(e.validation).join(' '):e.message||'Payment failed.'}finally{loading.value=false}}
async function saveSourcePayment(){clearMessages();loading.value=true;try{await AdminService.save('settlement',{settlementType:'Payment',sourceType:selected.value==='maintenance'?'Maintenance':'Compliance',sourceId:actionRecord.value.id,settledOn:actionDraft.value.settledOn,amount:Number(actionDraft.value.amount)});notice.value='Payment recorded.';closeAction();await load()}catch(e){error.value=e.validation?Object.values(e.validation).join(' '):e.message||'Payment failed.'}finally{loading.value=false}}
async function recordPrepayment(){if(!prepaymentEstimate.value?.available||!prepaymentConfirmed.value)return;clearMessages();loading.value=true;try{await AdminService.save('prepayment',{loanId:prepaymentDraft.value.loanId,paidOn:prepaymentDraft.value.paidOn,amount:prepaymentEstimate.value.appliedAmount,reason:prepaymentDraft.value.reason});notice.value='Prepayment recorded.';resetPrepayment();await load()}catch(e){error.value=e.validation?Object.values(e.validation).join(' '):e.message||'Prepayment failed.'}finally{loading.value=false}}
async function remove(record){if(!confirm('Delete this source record? Related records may prevent deletion.'))return;clearMessages();loading.value=true;try{await AdminService.remove(selected.value,record.id);notice.value='Record deleted.';await load()}catch(e){error.value=e.message||'Delete failed.'}finally{loading.value=false}}
async function resetData(){if(!confirm('Reset all KFE data? Create a backup first if needed.'))return;if(!confirm('Final confirmation: permanently delete all current KFE records?'))return;loading.value=true;clearMessages();try{await BackupService.resetData();notice.value='All canonical KFE data has been reset.'}catch(e){error.value=e.message||'Data reset failed.'}finally{loading.value=false}}
async function load(){loading.value=true;error.value='';try{for(const k of Object.keys(all.value))all.value[k]=await AdminService.list(k);records.value=selected.value&&!['prepayment','driverTarget','maintenanceRate'].includes(selected.value)?await AdminService.list(selected.value):[];performanceSnapshot.value=await PerformanceService.getSnapshot()}catch(e){error.value=e.message||'Unable to load Admin data.'}finally{loading.value=false}}
onMounted(load)
</script>

<template>
<section class="admin-page" aria-label="Admin">
<button v-if="selected||settingsOpen" class="back-button" @click="back">‹ Back</button>
<button class="settings-icon-button" :class="{active:settingsOpen}" @click="settingsOpen?settingsOpen=false:openSettings()" aria-label="Settings">⚙</button>

<template v-if="!selected&&!settingsOpen">
<div class="admin-list"><section v-for="group in groupedItems" :key="group.category" class="admin-category"><div class="category-label">{{group.category}}</div><button v-for="item in group.items" :key="item.key" class="admin-item" @click="openItem(item.key)"><span class="item-icon">{{item.icon}}</span><span class="item-title">{{item.title}}</span><span class="item-arrow">›</span></button></section></div>
</template>

<template v-else-if="settingsOpen">
<section class="settings-screen"><div class="settings-menu"><button v-for="item in settingsMenu" :key="item.key" class="settings-item" :class="{active:settingsSelected===item.key}" @click="chooseSetting(item.key)"><span>{{item.icon}}</span><strong>{{item.title}}</strong><span>›</span></button></div><section v-if="settingsSelected==='backup'" class="settings-panel"><h2>Backup &amp; Restore</h2><BackupRestorePanel/></section><section v-else-if="settingsSelected==='application'" class="settings-panel"><h2>Application Settings</h2><div class="theme-selector"><button :class="{active:themeSettings.mode==='light'}" @click="chooseTheme('light')">☀ Light</button><button :class="{active:themeSettings.mode==='dark'}" @click="chooseTheme('dark')">☾ Dark</button><button :class="{active:themeSettings.mode==='auto'}" @click="chooseTheme('auto')">◐ Auto</button></div></section><section v-else-if="settingsSelected==='synthetic'" class="settings-panel"><h2>Synthetic Data</h2><SyntheticDataPanel/></section><section v-else class="settings-panel"><h2>Data Reset</h2><p>This permanently clears canonical KFE business records.</p><button class="danger-button" :disabled="loading" @click="resetData">Reset all data</button></section></section>
</template>

<template v-else>
<section class="detail-screen"><div class="detail-title"><span class="item-icon">{{currentItem.icon}}</span><div><div class="category-label">{{currentItem.category}}</div><h1>{{currentItem.title}}</h1></div></div><p v-if="error" class="message error">{{error}}</p><p v-if="notice" class="message notice">✓ {{notice}}</p>

<template v-if="selected==='driverTarget'">
<section class="clean-card"><div class="card-heading"><strong>Monthly driver target</strong><span>{{targetDraft.month}}</span></div><div class="form-grid"><label><span>Driver</span><select v-model="targetDraft.driverId"><option value="">Select driver</option><option v-for="d in all.driver" :key="d.id" :value="d.id">{{label('driver',d)}}</option></select></label><label><span>Month</span><input v-model="targetDraft.month" type="month"></label><label><span>Monthly target</span><input v-model.number="targetDraft.desiredDriverProfit" type="number" min="0" step="0.01"></label></div><p class="rule-note">The saved target applies to the selected month as a whole. Changing it on the 1st or 15th does not split the month.</p><button class="primary wide" :disabled="loading" @click="saveTarget">Save monthly target</button></section><section class="history-card"><div class="category-label">TARGET HISTORY</div><article v-for="row in targetHistory" :key="row.id" class="history-row"><div><strong>{{driverNames[row.values?.driverId]||row.values?.driverId}}</strong><span>{{String(row.values?.effectiveFrom||'').slice(0,7)}}</span></div><strong>{{money(row.values?.desiredDriverProfit)}}</strong></article><div v-if="!targetHistory.length" class="empty">No target history yet.</div></section>
</template>

<template v-else-if="selected==='maintenanceRate'">
<section class="clean-card"><div class="card-heading"><div><strong>Current maintenance per KM</strong><span>Effective from {{currentMaintenanceRate?.values?.effectiveFrom||'—'}}</span></div><strong class="big-value">{{currentMaintenanceRate?.values?.maintenanceProvisionPerKm!=null?'₹'+Number(currentMaintenanceRate.values.maintenanceProvisionPerKm).toFixed(2):'—'}} / km</strong></div><div class="form-grid"><label><span>New rate per KM</span><input v-model.number="maintenanceRateDraft.rate" type="number" min="0" step="0.01"></label><label><span>Change date</span><input v-model="maintenanceRateDraft.changeDate" type="date"></label></div><p class="rule-note">The new rate applies from the change date until another change is made. Historical calculations use the rate applicable on their original date.</p><button class="primary wide" :disabled="loading" @click="saveMaintenanceRate">Save new rate</button></section><section class="history-card"><div class="category-label">RATE HISTORY</div><article v-for="row in maintenanceHistory" :key="row.id" class="history-row"><div><strong>{{row.values?.effectiveFrom}}</strong></div><strong>₹{{Number(row.values?.maintenanceProvisionPerKm||0).toFixed(2)}} / km</strong></article><div v-if="!maintenanceHistory.length" class="empty">No rate history yet.</div></section>
</template>

<template v-else-if="selected==='prepayment'">
<section class="clean-card"><div class="card-heading"><strong>Loan prepayment</strong><span>Calculate first. Nothing is recorded until confirmation.</span></div><div class="form-grid"><label><span>Loan</span><select v-model="prepaymentDraft.loanId" @change="selectPrepaymentLoan($event.target.value)"><option value="">Select loan</option><option v-for="loan in all.loan" :key="loan.id" :value="loan.id">{{label('loan',loan)}}</option></select></label><label><span>Current remaining</span><input :value="money(selectedPrepaymentPosition?.outstandingPrincipal||0)" readonly></label><label><span>Prepayment amount</span><input v-model.number="prepaymentDraft.amount" type="number" min="0" step="0.01"></label><label><span>Payment date</span><input v-model="prepaymentDraft.paidOn" type="date"></label></div><label class="wide-field"><span>Reason</span><textarea v-model="prepaymentDraft.reason"></textarea></label><button class="primary wide" :disabled="!prepaymentDraft.loanId||Number(prepaymentDraft.amount)<=0||loading" @click="prepaymentCalculated=true">Calculate effect</button><div v-if="prepaymentCalculated&&prepaymentEstimate" class="calculation-box"><div v-if="prepaymentEstimate.available" class="metric-grid"><div><span>Prepayment</span><strong>{{money(prepaymentEstimate.appliedAmount)}}</strong></div><div><span>Remaining after</span><strong>{{money(prepaymentEstimate.remainingAfter)}}</strong></div><div><span>Reduced tenure</span><strong>{{prepaymentEstimate.reducedMonths}} months</strong></div><div><span>Interest remaining</span><strong>{{money(prepaymentEstimate.interestRemainingAfter)}}</strong></div></div><p v-else class="message error">{{prepaymentEstimate.reason}}</p><template v-if="prepaymentEstimate.available"><label class="confirm-line"><input v-model="prepaymentConfirmed" type="checkbox"> I confirm this calculated prepayment.</label><button class="primary wide" :disabled="!prepaymentConfirmed||loading" @click="recordPrepayment">Continue to pay</button></template></div></section>
</template>

<template v-else-if="masterMode">
<div v-if="!masterSelected">
  <div class="detail-actions"><button class="primary" @click="add">＋ Create {{currentDefinition?.createLabel||currentItem.title}}</button></div>
  <section v-if="selected==='compliance'||selected==='maintenance'" class="clean-card provision-total">
