istory</span><small v-for="x in loanHistory(record).slice(0,5)" :key="x.kind+x.date+x.amount">{{x.kind}} · {{x.date?.slice(0,10)}} · {{money(x.amount)}}</small></div><div v-if="actionRecord?.id===record.id&&actionKey==='loanPayment'" class="calculation-box"><div class="form-grid"><label><span>Payment date</span><input v-model="actionDraft.paidOn" type="date"></label><label><span>Amount paid</span><input v-model.number="actionDraft.amount" type="number" min="0" step="0.01"></label></div><button class="primary wide" @click="paymentCalculated=true">Calculate payment</button><div v-if="loanPaymentPreview?.available" class="metric-grid"><div v-for="a in loanPaymentPreview.allocations" :key="a.obligationId"><span>EMI {{a.obligationId.split(':').at(-1)}}</span><strong>{{money((a.overdueInterest||0)+(a.scheduledInterest||0)+(a.scheduledPrincipal||0))}}</strong></div></div><p v-else-if="loanPaymentPreview" class="message error">{{loanPaymentPreview.reason}}</p><label v-if="loanPaymentPreview?.available" class="confirm-line"><input v-model="paymentConfirmed" type="checkbox"> I confirm this payment allocation.</label><button v-if="loanPaymentPreview?.available" class="primary wide" :disabled="!paymentConfirmed||loading" @click="saveLoanPayment">Confirm &amp; record payment</button></div></div><template v-else-if="selected==='maintenance'||selected==='compliance'"><div class="loan-summary"><div class="metric-grid"><div><span>Amount</span><strong>{{money(entityFinancial(record).cost)}}</strong></div><div><span>Paid</span><strong>{{money(entityFinancial(record).paid)}}</strong></div><div><span>Remaining</span><strong>{{money(entityFinancial(record).remaining)}}</strong></div></div><button class="secondary wide" @click="openAction('settlement',record)">Record payment</button><div v-if="sourceHistory(record).length" class="history-inline"><span>Payment history</span><small v-for="x in sourceHistory(record).slice(0,5)" :key="x.id">{{x.settledOn?.slice(0,10)}} · {{money(x.amount)}}</